from django.db import migrations, models


def tipo_segun_descripcion(apps, schema_editor):
    """Los camiones que ya existen toman su tipo de lo que dice la descripción."""
    Camion = apps.get_model("nucleo", "Camion")
    for camion in Camion.objects.all():
        texto = camion.descripcion.lower()
        if "furg" in texto:
            camion.tipo = "FURGON"
        else:
            camion.tipo = "SENCILLO"
        # La flota de reparto es de furgones y camiones: el tractocamión de los datos de prueba pasa a camión.
        if "tracto" in texto:
            camion.descripcion = "Camión sencillo 8 toneladas"
        camion.save(update_fields=["tipo", "descripcion"])


